118		const candidates: Array<{ path: string; offset: number }> = [];
119		for (const path of await files(laneRoot)) {
120			const bytes = await readFile(path);
121			const offset = bytes.indexOf(expected);
122			if (offset >= 0) {
123				if (bytes.lastIndexOf(expected) !== offset)
124					throw new Error('German heading semantic seam is not unique within its file');
125				candidates.push({ path, offset });
126			}
127		}
128		if (candidates.length !== 1)
129			throw new Error('German heading semantic seam is not unique across target output');
130		const target = candidates[0]!;
131		const before = await readFile(target.path);
132		const mutated = Buffer.from(before);
133		Buffer.alloc(expected.length, 'X').copy(mutated, target.offset);
134		const beforeSha256 = sha256(before);
135		const mutatedSha256 = sha256(mutated);
136		let intendedFailure = false;
137		try {
138			await writeFile(target.path, mutated);
139			try {
140				await executeReactBoilerplateZeroSwWitnessRun({
141					lane: 'migrated',
142					pass: 1,
143					laneRoot,
144					receiptRoot: join(stageRoot, 'semantic-mutation-receipt'),
145				});
146			} catch (error) {
147				const message = error instanceof Error ? error.message : String(error);
148				intendedFailure = message.includes(
149					'Beginnen Sie Ihr nächstes React Projekt in Sekunden',
150				);
151			}
152		} finally {
153			await writeFile(target.path, before);
154		}
155		const afterRestoreSha256 = sha256(await readFile(target.path));
156		if (!intendedFailure || afterRestoreSha256 !== beforeSha256)
157			throw new Error('German heading mutation was not exact red and byte-restored');
158		const restoredRaw = await executeReactBoilerplateZeroSwWitnessRun({
159			lane: 'migrated',
160			pass: 1,
161			laneRoot,
162			receiptRoot: join(stageRoot, 'semantic-restoration-receipt'),
163		});
164		const restored = restoredRaw as WitnessReactBoilerplateZeroSwRun;
165		if (witnessReactBoilerplateZeroSwBehaviorDigest(restored) !== behaviorDigest)
166			throw new Error('German heading restored browser behavior differs');
167		return {
168			failure: 'witness-semantic-assertion',
169			intendedFailure: true,
170			path: relative(laneRoot, target.path),
171			beforeSha256,
172			mutatedSha256,
173			afterRestoreSha256,
174			restoredByteIdentically: true,
175			restoredRun: 'pass',
176		};
177	}
