312	async function appendAggregate(
313		receipt: WitnessReactBoilerplateZeroSwReceipt,
314		canonicalReceipt: ReactBoilerplateZeroSwReceipt,
315	): Promise<void> {
316		const aggregate = JSON.parse(await readFile(aggregatePath, 'utf8')) as {
317			fixtures?: Array<Record<string, unknown>>;
318		};
319		if (!Array.isArray(aggregate.fixtures)) throw new Error('Corpus aggregate fixtures are absent');
320		const migrationMember = {
321			id: 'react-boilerplate-v4-zero-sw',
322			framework: 'react',
323			track: 'current-zero-service-worker-policy-reconciliation',
324			bundler: 'webpack-4.30.0-to-vite-8.0.16',
325			runtime: 'node-16.20.2-to-node-24.15.0',
326			result: 'pass',
327			receipt: 'evidence/runs/react-boilerplate-v4-zero-sw/t693-run.json',
328			digest: canonicalReceipt.integrity.canonicalDigest,
329		};
330		const member = witnessReactBoilerplateZeroSwAggregateMember(receipt.integrity.canonicalDigest);
331		const migrationIndex = aggregate.fixtures.findIndex((item) => item.id === migrationMember.id);
332		if (migrationIndex >= 0) aggregate.fixtures[migrationIndex] = migrationMember;
333		else aggregate.fixtures.push(migrationMember);
334		const index = aggregate.fixtures.findIndex((item) => item.id === member.id);
335		if (index >= 0) aggregate.fixtures[index] = member;
336		else aggregate.fixtures.push(member);
337		await writeFile(aggregatePath, `${JSON.stringify(aggregate, null, 2)}\n`);
338	}
