340	export async function runWitnessReactBoilerplateZeroSw(): Promise<WitnessReactBoilerplateZeroSwReceipt> {
341		if (
342			process.env.VERSIONLESS_NETWORK_MODE !== 'offline' ||
343			process.env.NPM_CONFIG_OFFLINE !== 'true'
344		)
345			throw new Error('React Boilerplate zero-SW Witness requires dual offline controls');
346		if (await exists(witnessEvidence))
347			throw new Error('React Boilerplate zero-SW Witness output collision');
348		await protectedHashes();
349		const provenance = await verifyLinkedWitnessProvenance(root);
350		const profile = JSON.parse(await readFile(profilePath, 'utf8')) as { result?: string };
351		if (profile.result !== 'build-profile-complete-not-promoted')
352			throw new Error('React Boilerplate zero-SW build profile is absent or differs');
353		const lanes = await stageInputs();
354		const runs = await executeRuns(lanes);
355		const mutations = {
356			semantic: await semanticMutation(lanes.migrated, runs[0]!.behaviorDigest),
357			serviceWorker: await serviceWorkerMutation(),
358		};
359		const canonicalReceipt = await writeFixtureReceipt(runs, mutations);
360		const canonicalBytes = await readFile(fixtureReceiptPath);
361		const receipt: WitnessReactBoilerplateZeroSwReceipt = {
362			schemaVersion: WITNESS_REACT_BOILERPLATE_ZERO_SW_SCHEMA,
363			result: 'pass',
364			fixture: REACT_BOILERPLATE_ZERO_SW_FIXTURE,
365			source,
366			provenance,
367			canonicalReceipt: {
368				path: relative(root, fixtureReceiptPath),
369				canonicalDigest: canonicalReceipt.integrity.canonicalDigest,
370				sha256: sha256(canonicalBytes),
371			},
372			supersedes: {
373				...REACT_BOILERPLATE_ZERO_SW_SUPERSEDES.witness,
374				scope: 'current-zero-service-worker-policy-only',
375				originalOfflineFirstEvidenceRetained: true,
376			},
377			runs,
378			mutations,
379			zeroServiceWorker: zeroObservation,
380			readiness: {
381				reactLineage: { ready: 1, total: 4, counted: true },
382				alignedReact: { ready: 0, total: 4, counted: false },
383				overall: { ready: 3, total: 12 },
384			},
385			locality: { mode: 'offline', successfulNonLoopback: 0, osWideIsolation: false },
386			nonclaims: [
387				'This is one already-counted React lineage and does not establish generic React support or advance readiness before Judge audit.',
388				'T060 original offline-first behavior remains valid; this receipt supersedes it only for current zero-service-worker policy.',
389				'Drag remains not-tested because the application has no genuine drag surface.',
390				'Locality is process-scoped and does not establish OS-wide isolation.',
391				'Receipts prove reproducibility and hash integrity, not certification, authenticity, signer identity, compliance, or an earned SLSA level.',
392			],
393			integrity: { algorithm: 'sha256', canonicalDigest: '' },
394		};
395		receipt.integrity.canonicalDigest = witnessReactBoilerplateZeroSwDigest(receipt);
396		parseWitnessReactBoilerplateZeroSwReceipt(receipt);
397		await mkdir(witnessEvidence, { recursive: true });
398		await writeFile(join(witnessEvidence, 'receipt.json'), `${canonicalize(receipt)}\n`, {
399			flag: 'wx',
400		});
401		await writeFile(
402			join(witnessEvidence, 'receipt.md'),
403			renderWitnessReactBoilerplateZeroSwReceipt(receipt),
404			{ flag: 'wx' },
405		);
406		await appendAggregate(receipt, canonicalReceipt);
407		await protectedHashes();
408		return receipt;
409	}
410	
411	export async function verifyWitnessReactBoilerplateZeroSw(
412		output = witnessEvidence,
413	): Promise<WitnessReactBoilerplateZeroSwReceipt> {
414		await protectedHashes();
415		const expectedProvenance = await verifyLinkedWitnessProvenance(root);
416		const receipt = parseWitnessReactBoilerplateZeroSwReceipt(
417			JSON.parse(await readFile(join(output, 'receipt.json'), 'utf8')),
418		);
419		if (canonicalize(receipt.provenance) !== canonicalize(expectedProvenance))
420			throw new Error('React Boilerplate zero-SW linked Witness provenance differs');
421		const canonicalBytes = await readFile(join(root, receipt.canonicalReceipt.path));
422		if (sha256(canonicalBytes) !== receipt.canonicalReceipt.sha256)
423			throw new Error('React Boilerplate zero-SW canonical receipt bytes drifted');
424		parseReactBoilerplateZeroSwReceipt(JSON.parse(canonicalBytes.toString('utf8')));
425		if (
426			(await readFile(join(output, 'receipt.md'), 'utf8')) !==
427			renderWitnessReactBoilerplateZeroSwReceipt(receipt)
428		)
429			throw new Error('React Boilerplate zero-SW human Witness receipt differs');
430		const serialized = canonicalize(receipt);
431		if (serialized.includes(root) || serialized.includes(process.env.USER ?? ''))
432			throw new Error('React Boilerplate zero-SW receipt leaks host identity');
433		return receipt;
434	}
435	
436	export async function main(args = process.argv.slice(2)): Promise<void> {
437		const publishIndex = args.indexOf('--publish');
438		const verifyIndex = args.indexOf('--verify');
439		if (args.includes('--run-twice') && publishIndex >= 0 && args[publishIndex + 1]) {
440			const output = resolve(root, args[publishIndex + 1]!);
441			if (output !== witnessEvidence)
442				throw new Error('React Boilerplate zero-SW publish path differs');
443			const receipt = await runWitnessReactBoilerplateZeroSw();
444			process.stdout.write(
445				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
446			);
447			return;
448		}
449		if (verifyIndex >= 0 && args[verifyIndex + 1]) {
450			const receipt = await verifyWitnessReactBoilerplateZeroSw(
451				resolve(root, args[verifyIndex + 1]!),
452			);
453			process.stdout.write(
454				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
455			);
456			return;
457		}
458		throw new Error(
459			'React Boilerplate zero-SW Witness runner requires --run-twice --publish <dir> or --verify <dir>',
460		);
461	}
462	
463	if (basename(process.argv[1] ?? '') === 'react-boilerplate-zero-sw-run.ts')
464		main().catch((error: unknown) => {
465			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
466			process.exitCode = 1;
467		});
