146	}
147	
148	async function inventory(directory: string) {
149		const files = await Promise.all(
150			(await filesBelow(directory)).map(async (file) => ({
151				path: relative(directory, file).split(sep).join('/'),
152				sha256: sha256(await readFile(file)),
153			})),
154		);
155		return { files, digest: sha256(canonicalize(files)) };
156	}
157	
158	function workerOutputs(files: readonly { path: string }[]): string[] {
159		return files
160			.map((file) => file.path)
161			.filter((path) => {
162				const name = basename(path).toLowerCase();
163				return (
164					name === 'sw.js' ||
165					name === 'service-worker.js' ||
166					name.includes('precache-manifest') ||
167					name.startsWith('workbox-') ||
168					name.endsWith('.worker.js')
169				);
170			})
171			.sort();
172	}
173	
174	function removeExactlyOnce(source: string, span: string, label: string): string {
175		const first = source.indexOf(span);
176		if (first < 0 || source.lastIndexOf(span) !== first)
177			throw new Error(`Zero-SW exact ${label} span differs`);
178		return `${source.slice(0, first)}${source.slice(first + span.length)}`;
179	}
180	
181	function removeOfflinePlugin(source: string): string {
182		const withoutRequire = removeExactlyOnce(source, offlineRequire, 'OfflinePlugin require');
183		const start = withoutRequire.indexOf(offlinePluginStart);
184		const end = withoutRequire.indexOf(compressionStart);
185		if (
186			start < 0 ||
187			end <= start ||
188			withoutRequire.lastIndexOf(offlinePluginStart) !== start ||
189			withoutRequire.lastIndexOf(compressionStart) !== end
190		)
191			throw new Error('Zero-SW exact OfflinePlugin execution span differs');
192		const result = `${withoutRequire.slice(0, start)}${withoutRequire.slice(end)}`;
193		if (result.includes('OfflinePlugin') || result.includes("require('offline-plugin')"))
194			throw new Error('Zero-SW webpack configuration retained OfflinePlugin execution');
195		return result;
196	}
197	
198	async function copySource(source: string, destination: string): Promise<void> {
199		await cp(source, destination, {
200			recursive: true,
201			filter: (path) => !['node_modules', 'build', 'build-vite'].includes(basename(path)),
202		});
203		await symlink(join(source, 'node_modules'), join(destination, 'node_modules'));
204		if (!(await lstat(join(destination, 'node_modules'))).isSymbolicLink())
205			throw new Error('Derived dependency closure is not linked');
206	}
207	
208	async function applyProfile(lane: string): Promise<{
209		appBefore: string;
210		appAfter: string;
211		webpackBefore: string;
212		webpackAfter: string;
213	}> {
214		const appPath = join(lane, 'app/app.js');
215		const webpackPath = join(lane, 'internals/webpack/webpack.prod.babel.js');
216		const app = await readFile(appPath, 'utf8');
217		const webpack = await readFile(webpackPath, 'utf8');
218		const nextApp = removeExactlyOnce(app, registrationBlock, 'runtime registration');
219		const nextWebpack = removeOfflinePlugin(webpack);
220		await writeFile(appPath, nextApp);
221		await writeFile(webpackPath, nextWebpack);
222		return {
223			appBefore: sha256(app),
224			appAfter: sha256(nextApp),
225			webpackBefore: sha256(webpack),
226			webpackAfter: sha256(nextWebpack),
227		};
228	}
229	
230	async function webpackBuild(lane: string) {
231		await rm(join(lane, 'build'), { recursive: true, force: true });
232		const result = await execute(lane, node16Root, join(node16Root, 'bin/npm'), ['run', 'build']);
233		const log = normalizedLog(`${result.stdout}${result.stderr}`);
234		if (!log.toLowerCase().includes('webpack') || log.toLowerCase().includes('vite'))
235			throw new Error('Zero-SW baseline did not prove webpack 4');
236		const output = await inventory(join(lane, 'build'));
237		const workers = workerOutputs(output.files);
238		if (workers.length !== 0)
239			throw new Error(`Zero-SW baseline emitted workers: ${workers.join(',')}`);
240		return output;
241	}
242	
243	async function viteBuild(lane: string) {
244		await rm(join(lane, 'build-vite'), { recursive: true, force: true });
245		const result = await execute(lane, node24Root, join(node24Root, 'bin/node'), [
246			'--experimental-strip-types',
247			viteCli,
248			'build',
249			'--config',
250			viteConfig,
251		]);
252		const log = normalizedLog(`${result.stdout}${result.stderr}`);
253		if (!log.includes('vite v8.0.16') || log.toLowerCase().includes('webpack'))
254			throw new Error('Zero-SW target did not prove Vite 8.0.16 without webpack');
255		const output = await inventory(join(lane, 'build-vite'));
256		const workers = workerOutputs(output.files);
257		if (workers.length !== 0)
258			throw new Error(`Zero-SW target emitted workers: ${workers.join(',')}`);
259		return output;
260	}
261	
262	async function canonicalizeLegacyWorker(output: string): Promise<void> {
263		const worker = join(output, 'sw.js');
264		const source = await readFile(worker, 'utf8');
265		const lines = source.split('\n');
266		const versionLines = lines.filter((line) => line.startsWith('  "version": "'));
267		if (versionLines.length !== 1)
268			throw new Error('Zero-SW mutation legacy worker version seam differs');
269		const canonical = lines
270			.map((line) =>
271				line.startsWith('  "version": "') ? '  "version": "versionless-deterministic",' : line,
272			)
273			.join('\n');
274		await writeFile(worker, canonical);
275		await writeFile(`${worker}.gz`, gzipSync(canonical));
276	}
277	
278	async function protectedHashes(manifest: Manifest): Promise<Record<string, string>> {
279		const hashes = Object.fromEntries(
280			await Promise.all(
281				Object.entries(protectedPaths).map(async ([name, path]) => [
282					name,
283					sha256(await readFile(join(root, path))),
284				]),
285			),
286		);
287		if (canonicalize(hashes) !== canonicalize(manifest.protected))
288			throw new Error('Protected T060 or original Witness hash differs');
289		return hashes;
290	}
291	
292	async function preflight(): Promise<{ manifest: Manifest; protected: Record<string, string> }> {
293		const manifest = JSON.parse(
294			await readFile(join(fixtureRoot, 'fixture.json'), 'utf8'),
295		) as Manifest;
296		const baseline = join(root, manifest.inputs.baseline);
297		const target = join(root, manifest.inputs.target);
298		for (const lane of [baseline, target]) {
299			if (sha256(await readFile(join(lane, 'app/app.js'))) !== manifest.inputs.appSha256)
300				throw new Error('Accepted composed app.js input differs');
301			if (
302				sha256(await readFile(join(lane, 'internals/webpack/webpack.prod.babel.js'))) !==
303				manifest.inputs.webpackProductionSha256
304			)
305				throw new Error('Accepted composed webpack production input differs');
306		}
307		if (
308			(
309				await execute(root, node16Root, join(node16Root, 'bin/node'), ['--version'])
310			).stdout.trim() !== 'v16.20.2' ||
311			(
312				await execute(root, node24Root, join(node24Root, 'bin/node'), ['--version'])
313			).stdout.trim() !== 'v24.15.0' ||
314			sha256(await readFile(join(root, manifest.browser.executable))) !== manifest.browser.sha256
315		)
316			throw new Error('Pinned zero-SW runtime or browser differs');
317		return { manifest, protected: await protectedHashes(manifest) };
318	}
319	
320	async function writeTerminal(error: unknown): Promise<void> {
321		if (await exists(terminalPath)) return;
322		await mkdir(evidenceRoot, { recursive: true });
323		const unsigned = {
324			schemaVersion: 'versionless.react-boilerplate-zero-sw-t693-terminal.v1',
325			result: 'terminal-failure',
326			promotion: 'none',
327			failure: error instanceof Error ? error.message : String(error),
328			scores: { react: '1/4', alignedReact: '0/4', total: '3/12' },
329		};
330		await writeFile(
331			terminalPath,
332			`${canonicalize({ ...unsigned, integrity: { algorithm: 'sha256', canonicalDigest: sha256(canonicalize(unsigned)) } })}\n`,
333			{ flag: 'wx' },
334		);
335	}
336	
337	export async function runReactBoilerplateZeroSw(): Promise<void> {
338		const prepared = await preflight();
339		if ((await exists(evidenceRoot)) || (await exists(workRoot)) || (await exists(stageRoot)))
340			throw new Error('T693 output collision');
341		try {
342			await mkdir(artifactsRoot, { recursive: true });
343			await mkdir(workRoot, { recursive: true });
344			const baseline = join(workRoot, 'baseline');
345			const target = join(workRoot, 'target');
346			await copySource(join(root, prepared.manifest.inputs.baseline), baseline);
347			await copySource(join(root, prepared.manifest.inputs.target), target);
348			await writeFile(
349				join(target, 'index.html'),
350				await readFile(join(root, 'fixtures/react-boilerplate-v4-vite8/index.html')),
351			);
352			const removals = {
353				baseline: await applyProfile(baseline),
354				target: await applyProfile(target),
355			};
356			if (canonicalize(removals.baseline) !== canonicalize(removals.target))
357				throw new Error('Zero-SW removal is not symmetric across derived lanes');
358	
359			const baselineFirst = await webpackBuild(baseline);
360			const baselineSecond = await webpackBuild(baseline);
361			const targetFirst = await viteBuild(target);
362			const targetSecond = await viteBuild(target);
363			if (
364				canonicalize(baselineFirst) !== canonicalize(baselineSecond) ||
365				canonicalize(targetFirst) !== canonicalize(targetSecond)
366			)
367				throw new Error('Zero-SW build outputs are not byte-identical');
368	
369			const mutation = join(workRoot, 'zero-sw-mutation');
370			await copySource(join(root, prepared.manifest.inputs.baseline), mutation);
371			const mutationAppBefore = sha256(await readFile(join(mutation, 'app/app.js')));
372			const mutationWebpackBefore = sha256(
373				await readFile(join(mutation, 'internals/webpack/webpack.prod.babel.js')),
374			);
375			await rm(join(mutation, 'build'), { recursive: true, force: true });
376			await execute(mutation, node16Root, join(node16Root, 'bin/npm'), ['run', 'build']);
377			await canonicalizeLegacyWorker(join(mutation, 'build'));
378			const mutationOutput = await inventory(join(mutation, 'build'));
379			const observedWorkerOutputs = workerOutputs(mutationOutput.files);
380			if (!observedWorkerOutputs.includes('sw.js'))
381				throw new Error('Zero-SW mutation did not make the worker-output guard red');
382			await mkdir(stageRoot, { recursive: true });
383			await cp(join(mutation, 'build'), join(stageRoot, 'mutation-output'), { recursive: true });
384			if (
385				sha256(await readFile(join(mutation, 'app/app.js'))) !== mutationAppBefore ||
386				sha256(await readFile(join(mutation, 'internals/webpack/webpack.prod.babel.js'))) !==
387					mutationWebpackBefore
388			)
389				throw new Error('Zero-SW mutation source/config restoration differs');
390			const baselineRestored = await webpackBuild(baseline);
391			if (canonicalize(baselineRestored) !== canonicalize(baselineFirst))
392				throw new Error('Zero-SW mutation build-digest restoration differs');
393	
394			const profile = {
395				schemaVersion: 'versionless.react-boilerplate-zero-sw-build-profile.v1',
396				result: 'build-profile-complete-not-promoted',
397				source: prepared.manifest.source,
398				protected: prepared.protected,
399				removals,
400				builds: {
401					baseline: {
402						runtime: 'node-16.20.2',
403						bundler: 'webpack-4.30.0',
404						first: baselineFirst,
405						second: baselineSecond,
406						equal: true,
407					},
408					target: {
409						runtime: 'node-24.15.0',
410						bundler: 'vite-8.0.16',
411						react: '18-compatible',
412						first: targetFirst,
413						second: targetSecond,
414						equal: true,
415						webpackExecuted: false,
416					},
417				},
418				zeroServiceWorker: { outputFiles: [] },
419				mutation: {
420					seam: 'exact-upstream-offline-plugin-registration-and-build-execution',
421					observedWorkerOutputs,
422					guard: 'intended-failure',
423					sourceConfigRestoration: 'byte-identical',
424					buildRestoration: 'digest-identical',
425				},
426				scores: { react: '1/4', alignedReact: '0/4', total: '3/12' },
427			};
428			await writeFile(profilePath, `${canonicalize(profile)}\n`, { flag: 'wx' });
429			await writeFile(join(artifactsRoot, 'build.json'), `${canonicalize(profile.builds)}\n`, {
430				flag: 'wx',
431			});
432			await writeFile(
433				join(artifactsRoot, 'zero-sw-mutation.json'),
434				`${canonicalize(profile.mutation)}\n`,
435				{ flag: 'wx' },
436			);
437			await protectedHashes(prepared.manifest);
438		} catch (error) {
439			await writeTerminal(error);
440			throw error;
441		}
442	}
443	
444	export async function main(args = process.argv.slice(2)): Promise<void> {
445		if (
446			args.length === 3 &&
447			args[0] === '--preflight' &&
448			args[1] === '--namespace' &&
449			args[2] === 't693'
450		) {
451			await preflight();
452			process.stdout.write('{"preflight":"pass"}\n');
453			return;
454		}
455		if (
456			args.length === 3 &&
457			args[0] === '--run' &&
458			args[1] === '--namespace' &&
459			args[2] === 't693'
460		) {
461			if (
462				process.env.VERSIONLESS_NETWORK_MODE !== 'offline' ||
463				process.env.NPM_CONFIG_OFFLINE !== 'true'
464			)
465				throw new Error('T693 run requires explicit dual offline controls');
466			await runReactBoilerplateZeroSw();
467			process.stdout.write(
468				`${canonicalize({ result: 'build-profile-complete-not-promoted' })}\n`,
469			);
470			return;
471		}
472		throw new Error('T693 runner requires --preflight --namespace t693 or --run --namespace t693');
473	}
474	
475	if (basename(process.argv[1] ?? '') === 'react-boilerplate-v4-zero-sw-run.ts')
476		main().catch((error: unknown) => {
477			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
478			process.exitCode = 1;
479		});
